@router.post("/dependencies/", response_model=schemas.Dependency, status_code=status.HTTP_201_CREATED)
def create_dependency(
    dependency: schemas.DependencyCreate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    # Validate that either prerequisite_id or prerequisite_subtask_id is provided
    if not (dependency.prerequisite_id or dependency.prerequisite_subtask_id):
        raise HTTPException(status_code=400, detail="Either prerequisite_id or prerequisite_subtask_id must be provided")
    if not (dependency.dependent_id or dependency.dependent_subtask_id):
        raise HTTPException(status_code=400, detail="Either dependent_id or dependent_subtask_id must be provided")

    # Validate that the prerequisite exists and current_user has access to it
    if dependency.prerequisite_id:
        prerequisite_task = crud.get_task(db, task_id=dependency.prerequisite_id)
        if prerequisite_task is None:
            raise HTTPException(status_code=404, detail="Prerequisite task not found")
        db_project = crud.get_project(db, project_id=prerequisite_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to access prerequisite task")
    elif dependency.prerequisite_subtask_id:
        prerequisite_subtask = crud.get_subtask(db, subtask_id=dependency.prerequisite_subtask_id)
        if prerequisite_subtask is None:
            raise HTTPException(status_code=404, detail="Prerequisite subtask not found")
        db_task = crud.get_task(db, task_id=prerequisite_subtask.parent_task_id)
        db_project = crud.get_project(db, project_id=db_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to access prerequisite subtask")

    # Validate that the dependent exists and current_user has access to it
    if dependency.dependent_id:
        dependent_task = crud.get_task(db, task_id=dependency.dependent_id)
        if dependent_task is None:
            raise HTTPException(status_code=404, detail="Dependent task not found")
        db_project = crud.get_project(db, project_id=dependent_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to access dependent task")
    elif dependency.dependent_subtask_id:
        dependent_subtask = crud.get_subtask(db, subtask_id=dependency.dependent_subtask_id)
        if dependent_subtask is None:
            raise HTTPException(status_code=404, detail="Dependent subtask not found")
        db_task = crud.get_task(db, task_id=dependent_subtask.parent_task_id)
        db_project = crud.get_project(db, project_id=db_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to access dependent subtask")

    return crud.create_dependency(db=db, dependency=dependency)

