@router.delete("/dependencies/{dependency_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_dependency(
    dependency_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_dependency = crud.get_dependency(db, dependency_id=dependency_id)
    if db_dependency is None:
        raise HTTPException(status_code=404, detail="Dependency not found")

    # Determine the parent project of the dependency and check permissions
    project_id_to_check = None
    if db_dependency.prerequisite_id:
        task = crud.get_task(db, task_id=db_dependency.prerequisite_id)
        if task:
            project_id_to_check = task.project_id
    elif db_dependency.prerequisite_subtask_id:
        subtask = crud.get_subtask(db, subtask_id=db_dependency.prerequisite_subtask_id)
        if subtask:
            task = crud.get_task(db, task_id=subtask.parent_task_id)
            if task:
                project_id_to_check = task.project_id

    if project_id_to_check:
        db_project = crud.get_project(db, project_id=project_id_to_check)
        if db_project is None or db_project.owner_id != current_user.id:
            # TODO: Add logic to check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to delete this dependency")
    else:
        # If no associated project could be found (shouldn't happen if data integrity is maintained)
        raise HTTPException(status_code=500, detail="Could not determine project for dependency")

    crud.delete_dependency(db=db, dependency_id=dependency_id)
    return

