import React, { useState, useEffect } from 'react';
import { Container, Typography, Box, Button, Dialog, DialogTitle, DialogContent, DialogActions, TextField } from '@mui/material';
import { useAuth } from '../context/AuthContext';
// import { getProjects, createProject, updateProject, deleteProject } from '../services/api'; // Assuming API service

interface Project {
  id: number;
  name: string;
  description: string;
  // Add other project fields
}

const ProjectListPage: React.FC = () => {
  const { user } = useAuth();
  const [projects, setProjects] = useState<Project[]>([]);
  const [open, setOpen] = useState(false);
  const [currentProject, setCurrentProject] = useState<Project | null>(null);

  useEffect(() => {
    // Fetch projects when component mounts or user changes
    if (user) {
      // In a real app, you'd fetch from your API
      // getProjects(user.id).then(data => setProjects(data));
      setProjects([
        { id: 1, name: 'Project Alpha', description: 'Description for Alpha' },
        { id: 2, name: 'Project Beta', description: 'Description for Beta' },
      ]);
    }
  }, [user]);

  const handleClickOpen = (project: Project | null = null) => {
    setCurrentProject(project);
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setCurrentProject(null);
  };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const newProject = {
      name: data.get('name') as string,
      description: data.get('description') as string,
    };

    if (currentProject) {
      // Update project
      console.log('Updating project:', currentProject.id, newProject);
      // updateProject(currentProject.id, newProject).then(() => { /* refresh projects */ });
    } else {
      // Create new project
      console.log('Creating new project:', newProject);
      // createProject(newProject).then(() => { /* refresh projects */ });
    }
    handleClose();
  };

  const handleDelete = (projectId: number) => {
    console.log('Deleting project:', projectId);
    // deleteProject(projectId).then(() => { /* refresh projects */ });
  };

  return (
    <Container maxWidth="lg">
      <Box sx={{ my: 4 }}>
        <Typography variant="h4" component="h1" gutterBottom>
          My Projects
        </Typography>
        <Button variant="contained" onClick={() => handleClickOpen()}>
          Create New Project
        </Button>

        <Box sx={{ mt: 3 }}>
          {projects.map((project) => (
            <Box key={project.id} sx={{ p: 2, border: '1px solid #ccc', mb: 2 }}>
              <Typography variant="h6">{project.name}</Typography>
              <Typography variant="body2">{project.description}</Typography>
              <Button onClick={() => handleClickOpen(project)}>Edit</Button>
              <Button color="error" onClick={() => handleDelete(project.id)}>Delete</Button>
            </Box>
          ))}
        </Box>

        <Dialog open={open} onClose={handleClose}>
          <DialogTitle>{currentProject ? 'Edit Project' : 'Create Project'}</DialogTitle>
          <DialogContent>
            <Box component="form" onSubmit={handleSubmit} noValidate sx={{ mt: 1 }}>
              <TextField
                margin="normal"
                required
                fullWidth
                id="name"
                label="Project Name"
                name="name"
                defaultValue={currentProject?.name || ''}
                autoFocus
              />
              <TextField
                margin="normal"
                fullWidth
                id="description"
                label="Description"
                name="description"
                multiline
                rows={4}
                defaultValue={currentProject?.description || ''}
              />
              <Button
                type="submit"
                fullWidth
                variant="contained"
                sx={{ mt: 3, mb: 2 }}
              >
                {currentProject ? 'Update' : 'Create'}
              </Button>
            </Box>
          </DialogContent>
          <DialogActions>
            <Button onClick={handleClose}>Cancel</Button>
          </DialogActions>
        </Dialog>
      </Box>
    </Container>
  );
};

export default ProjectListPage;

import React, { useState, useEffect } from 'react';
