import React from 'react';
import { Typography, Box, List, ListItem, ListItemText, IconButton } from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';

// Define types for Task and Subtask (simplified)
interface Subtask {
  id: number;
  name: string;
  status: string;
}

interface Task {
  id: number;
  name: string;
  status: string;
  subtasks?: Subtask[];
}

interface TaskHierarchyProps {
  tasks: Task[];
  onEditTask?: (taskId: number) => void;
  onDeleteTask?: (taskId: number) => void;
  onEditSubtask?: (subtaskId: number) => void;
  onDeleteSubtask?: (subtaskId: number) => void;
}

const TaskHierarchy: React.FC<TaskHierarchyProps> = ({ 
  tasks, 
  onEditTask, 
  onDeleteTask, 
  onEditSubtask, 
  onDeleteSubtask 
}) => {
  return (
    <Box>
      <Typography variant="h6" gutterBottom>
        Tasks
      </Typography>
      <List>
        {tasks.map((task) => (
          <Box key={task.id} sx={{ border: '1px solid #eee', mb: 1, p: 1 }}>
            <ListItem
              secondaryAction={
                <>
                  {onEditTask && (
                    <IconButton edge="end" aria-label="edit" onClick={() => onEditTask(task.id)}>
                      <EditIcon />
                    </IconButton>
                  )}
                  {onDeleteTask && (
                    <IconButton edge="end" aria-label="delete" onClick={() => onDeleteTask(task.id)}>
                      <DeleteIcon />
                    </IconButton>
                  )}
                </>
              }
            >
              <ListItemText primary={task.name} secondary={`Status: ${task.status}`} />
            </ListItem>
            {task.subtasks && task.subtasks.length > 0 && (
              <List sx={{ pl: 4 }}>
                {task.subtasks.map((subtask) => (
                  <ListItem
                    key={subtask.id}
                    secondaryAction={
                      <>
                        {onEditSubtask && (
                          <IconButton edge="end" aria-label="edit" onClick={() => onEditSubtask(subtask.id)}>
                            <EditIcon />
                          </IconButton>
                        )}
                        {onDeleteSubtask && (
                          <IconButton edge="end" aria-label="delete" onClick={() => onDeleteSubtask(subtask.id)}>
                            <DeleteIcon />
                          </IconButton>
                        )}
                      </>
                    }
                  >
                    <ListItemText primary={subtask.name} secondary={`Status: ${subtask.status}`} />
                  </ListItem>
                ))}
              </List>
            )}
          </Box>
        ))}
      </List>
    </Box>
  );
};

export default TaskHierarchy;

import React from 'react';
import Plot from 'react-plotly.js';
import { Layout, Data } from 'plotly.js';

interface GanttTask {
  id: number;
  name: string;
  start: string; // ISO 8601 date string
  end: string;   // ISO 8601 date string
  progress?: number; // 0-100
  dependencies?: number[]; // Array of task IDs this task depends on
  resource?: string; // e.g., assigned user
}

interface GanttChartProps {
  tasks: GanttTask[];
  title?: string;
}

const GanttChart: React.FC<GanttChartProps> = ({ tasks, title = 'Project Gantt Chart' }) => {
  const data: Partial<Data>[] = [
    {
      x: tasks.map(task => task.end),
      y: tasks.map(task => task.name),
      base: tasks.map(task => task.start),
      mode: 'lines',
      type: 'scatter',
      orientation: 'h',
      marker: {
        color: tasks.map(task => {
          // Simple color coding based on status or progress (can be expanded)
          if (task.progress === 100) return 'green';
          if (task.progress && task.progress > 0) return 'orange';
          return 'blue';
        }),
        line: {
          color: 'black',
          width: 1,
        },
      },
      line: {
        width: 15,
        shape: 'spline',
      },
      // Custom data for tooltips or other interactions
      customdata: tasks.map(task => ({
        id: task.id,
        progress: task.progress,
        dependencies: task.dependencies,
        resource: task.resource,
      })),
      hovertemplate: 
        '<b>Task:</b> %{y}<br>' +
        '<b>Start:</b> %{base|%Y-%m-%d}<br>' +
        '<b>End:</b> %{x|%Y-%m-%d}<br>' +
        '<b>Progress:</b> %{customdata.progress}%<br>' +
        '<b>Resource:</b> %{customdata.resource}<extra></extra>',
    },
  ];

  const layout: Partial<Layout> = {
    title: title,
    hovermode: 'closest',
    showlegend: false,
    xaxis: {
      type: 'date',
      title: 'Date',
    },
    yaxis: {
      automargin: true,
      title: 'Task',
      autorange: 'reversed', // Display tasks from top to bottom
    },
    margin: {
      l: 150, // Adjust left margin to prevent y-axis labels from being cut off
      r: 50,
      t: 80,
      b: 80,
    },
    height: 600,
    responsive: true,
  };

  return (
    <Plot
      data={data}
      layout={layout}
      style={{ width: '100%', height: '100%' }}
      useResizeHandler={true}
      config={{ responsive: true }}
    />
  );
};

export default GanttChart;

import React from 'react';
import { Typography, Box, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow } from '@mui/material';

interface CalendarEvent {
  id: number;
  title: string;
  startDate: Date;
  endDate: Date;
  type: 'project' | 'task'; // Or more specific types
}

interface CalendarChartProps {
  events: CalendarEvent[];
}

const CalendarChart: React.FC<CalendarChartProps> = ({ events }) => {
  // Simple calendar logic for demonstration
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentYear, currentMonth, 1).getDay(); // 0 for Sunday, 1 for Monday etc.

  const days: (number | null)[] = Array(firstDayOfMonth).fill(null);
  for (let i = 1; i <= daysInMonth; i++) {
    days.push(i);
  }

  const getEventsForDay = (day: number) => {
    const date = new Date(currentYear, currentMonth, day);
    return events.filter(event => 
      (event.startDate <= date && event.endDate >= date)
    );
  };

  return (
    <Box sx={{ my: 4 }}>
      <Typography variant="h6" gutterBottom>
        Calendar View ({new Date(currentYear, currentMonth).toLocaleString('default', { month: 'long', year: 'numeric' })})
      </Typography>
      <TableContainer component={Paper}>
        <Table sx={{ minWidth: 650 }} aria-label="simple calendar">
          <TableHead>
            <TableRow>
              {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((day) => (
                <TableCell key={day} align="center"><b>{day}</b></TableCell>
              ))}
            </TableRow>
          </TableHead>
          <TableBody>
            {Array(Math.ceil(days.length / 7)).fill(null).map((_, weekIndex) => (
              <TableRow key={weekIndex}>
                {days.slice(weekIndex * 7, (weekIndex + 1) * 7).map((day, dayIndex) => (
                  <TableCell key={dayIndex} align="center" sx={{ height: 100, verticalAlign: 'top', border: '1px solid #eee' }}>
                    {day && (
                      <>
                        <Typography variant="body2" fontWeight="bold">{day}</Typography>
                        <Box sx={{ mt: 1 }}>
                          {getEventsForDay(day).map(event => (
                            <Typography key={event.id} variant="caption" display="block" 
                                sx={{ 
                                  backgroundColor: event.type === 'project' ? 'primary.light' : 'secondary.light',
                                  color: 'white',
                                  borderRadius: 1,
                                  px: 0.5,
                                  mb: 0.5
                                }}
                            >
                              {event.title}
                            </Typography>
                          ))}
                        </Box>
                      </>
                    )}
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default CalendarChart;

import React, { useState } from 'react';
import {
  Box,
  Typography,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  IconButton,
  TextField,
  Button,
  Divider,
  Paper,
} from '@mui/material';
import AttachFileIcon from '@mui/icons-material/AttachFile';
import DeleteIcon from '@mui/icons-material/Delete';
import CommentIcon from '@mui/icons-material/Comment';

interface Attachment {
  id: number;
  filename: string;
  url: string; // URL to download the attachment
  uploadedBy: string;
  uploadedAt: string;
}

interface Comment {
  id: number;
  content: string;
  author: string;
  createdAt: string;
}

interface AttachmentsCommentsProps {
  itemId: number; // ID of the project, task, or subtask
  itemType: 'project' | 'task' | 'subtask';
  attachments: Attachment[];
  comments: Comment[];
  onUploadAttachment: (file: File) => void;
  onDeleteAttachment: (attachmentId: number) => void;
  onAddComment: (commentContent: string) => void;
  onDeleteComment: (commentId: number) => void;
}

const AttachmentsComments: React.FC<AttachmentsCommentsProps> = ({
  attachments,
  comments,
  onUploadAttachment,
  onDeleteAttachment,
  onAddComment,
  onDeleteComment,
}) => {
  const [newComment, setNewComment] = useState('');

  const handleCommentSubmit = () => {
    if (newComment.trim()) {
      onAddComment(newComment);
      setNewComment('');
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files.length > 0) {
      onUploadAttachment(event.target.files[0]);
      // Optionally clear the input
      event.target.value = '';
    }
  };

  return (
    <Box sx={{ mt: 4 }}>
      <Typography variant="h6" gutterBottom>
        Attachments & Comments
      </Typography>

      <Paper elevation={1} sx={{ p: 2, mb: 3 }}>
        <Typography variant="subtitle1" gutterBottom>
          Attachments
        </Typography>
        {attachments.length > 0 ? (
          <List>
            {attachments.map((attachment) => (
              <ListItem
                key={attachment.id}
                secondaryAction={
                  <IconButton edge="end" aria-label="delete" onClick={() => onDeleteAttachment(attachment.id)}>
                    <DeleteIcon />
                  </IconButton>
                }
              >
                <ListItemIcon>
                  <AttachFileIcon />
                </ListItemIcon>
                <ListItemText
                  primary={
                    <a href={attachment.url} target="_blank" rel="noopener noreferrer">
                      {attachment.filename}
                    </a>
                  }
                  secondary={`Uploaded by ${attachment.uploadedBy} on ${new Date(attachment.uploadedAt).toLocaleDateString()}`}
                />
              </ListItem>
            ))}
          </List>
        ) : (
          <Typography variant="body2" color="text.secondary">No attachments yet.</Typography>
        )}
        <Button
          variant="outlined"
          component="label"
          sx={{ mt: 2 }}
        >
          Upload Attachment
          <input type="file" hidden onChange={handleFileChange} />
        </Button>
      </Paper>

      <Paper elevation={1} sx={{ p: 2 }}>
        <Typography variant="subtitle1" gutterBottom>
          Comments
        </Typography>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <TextField
            fullWidth
            variant="outlined"
            size="small"
            placeholder="Add a comment..."
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            onKeyPress={(e) => {
              if (e.key === 'Enter') {
                handleCommentSubmit();
              }
            }}
          />
          <Button variant="contained" sx={{ ml: 1 }} onClick={handleCommentSubmit}>
            Post
          </Button>
        </Box>
        <List>
          {comments.length > 0 ? (
            comments.map((comment) => (
              <React.Fragment key={comment.id}>
                <ListItem
                  secondaryAction={
                    <IconButton edge="end" aria-label="delete" onClick={() => onDeleteComment(comment.id)}>
                      <DeleteIcon />
                    </IconButton>
                  }
                >
                  <ListItemIcon>
                    <CommentIcon />
                  </ListItemIcon>
                  <ListItemText
                    primary={comment.content}
                    secondary={`By ${comment.author} on ${new Date(comment.createdAt).toLocaleDateString()}`}
                  />
                </ListItem>
                <Divider component="li" />
              </React.Fragment>
            ))
          ) : (
            <Typography variant="body2" color="text.secondary">No comments yet.</Typography>
          )}
        </List>
      </Paper>
    </Box>
  );
};

export default AttachmentsComments;

import React, { useState } from 'react';
import {
  Box,
  Typography,
  List,
  ListItem,
  ListItemText,
  IconButton,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';

// Simplified types for tasks and subtasks for selection
interface SelectableItem {
  id: number;
  name: string;
  type: 'task' | 'subtask';
}

interface Dependency {
  id: number;
  prerequisite: SelectableItem;
  dependent: SelectableItem;
}

interface DependencyManagerProps {
  dependencies: Dependency[];
  availableItems: SelectableItem[]; // All tasks/subtasks that can be part of a dependency
  onAddDependency: (prerequisiteId: number, prerequisiteType: 'task' | 'subtask', dependentId: number, dependentType: 'task' | 'subtask') => void;
  onDeleteDependency: (dependencyId: number) => void;
}

const DependencyManager: React.FC<DependencyManagerProps> = ({
  dependencies,
  availableItems,
  onAddDependency,
  onDeleteDependency,
}) => {
  const [openAddDialog, setOpenAddDialog] = useState(false);
  const [prerequisite, setPrerequisite] = useState<string>('');
  const [dependent, setDependent] = useState<string>('');

  const handleOpenAddDialog = () => {
    setOpenAddDialog(true);
  };

  const handleCloseAddDialog = () => {
    setOpenAddDialog(false);
    setPrerequisite('');
    setDependent('');
  };

  const handleAddSubmit = () => {
    if (prerequisite && dependent) {
      const prereqItem = availableItems.find(item => `${item.type}-${item.id}` === prerequisite);
      const depItem = availableItems.find(item => `${item.type}-${item.id}` === dependent);

      if (prereqItem && depItem) {
        onAddDependency(prereqItem.id, prereqItem.type, depItem.id, depItem.type);
        handleCloseAddDialog();
      }
    }
  };

  return (
    <Box sx={{ mt: 4 }}>
      <Typography variant="h6" gutterBottom>
        Dependency Manager
      </Typography>

      <Button
        variant="contained"
        startIcon={<AddCircleOutlineIcon />}
        onClick={handleOpenAddDialog}
        sx={{ mb: 2 }}
      >
        Add Dependency
      </Button>

      <List>
        {dependencies.length > 0 ? (
          dependencies.map((dep) => (
            <ListItem
              key={dep.id}
              secondaryAction={
                <IconButton edge="end" aria-label="delete" onClick={() => onDeleteDependency(dep.id)}>
                  <DeleteIcon />
                </IconButton>
              }
            >
              <ListItemText
                primary={`${dep.prerequisite.name} (${dep.prerequisite.type}) -> ${dep.dependent.name} (${dep.dependent.type})`}
              />
            </ListItem>
          ))
        ) : (
          <Typography variant="body2" color="text.secondary">No dependencies defined.</Typography>
        )}
      </List>

      <Dialog open={openAddDialog} onClose={handleCloseAddDialog}>
        <DialogTitle>Add New Dependency</DialogTitle>
        <DialogContent>
          <FormControl fullWidth sx={{ mt: 2, mb: 1 }}>
            <InputLabel id="prerequisite-label">Prerequisite</InputLabel>
            <Select
              labelId="prerequisite-label"
              id="prerequisite-select"
              value={prerequisite}
              label="Prerequisite"
              onChange={(e) => setPrerequisite(e.target.value as string)}
            >
              {availableItems.map((item) => (
                <MenuItem key={`${item.type}-${item.id}`} value={`${item.type}-${item.id}`}>
                  {item.name} ({item.type})
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <FormControl fullWidth sx={{ mt: 1, mb: 2 }}>
            <InputLabel id="dependent-label">Dependent</InputLabel>
            <Select
              labelId="dependent-label"
              id="dependent-select"
              value={dependent}
              label="Dependent"
              onChange={(e) => setDependent(e.target.value as string)}
            >
              {availableItems.map((item) => (
                <MenuItem key={`${item.type}-${item.id}`} value={`${item.type}-${item.id}`}>
                  {item.name} ({item.type})
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseAddDialog}>Cancel</Button>
          <Button onClick={handleAddSubmit} variant="contained">Add</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default DependencyManager;

import React, { useState } from 'react';
import {
  Box,
  Typography,
  List,
  ListItem,
  ListItemText,
  IconButton,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from '@mui/material';
import PersonRemoveIcon from '@mui/icons-material/PersonRemove';
import PersonAddIcon from '@mui/icons-material/PersonAdd';

interface Collaborator {
  id: number;
  name: string; // Or email
  permissions: 'view' | 'edit' | 'admin';
}

interface ProjectSharingProps {
  projectId: number;
  ownerId: number; // ID of the project owner
  collaborators: Collaborator[];
  onInviteUser: (userId: number, permissions: 'view' | 'edit' | 'admin') => void;
  onChangePermissions: (collaboratorId: number, permissions: 'view' | 'edit' | 'admin') => void;
  onRemoveCollaborator: (collaboratorId: number) => void;
}

const ProjectSharing: React.FC<ProjectSharingProps> = ({
  projectId,
  ownerId,
  collaborators,
  onInviteUser,
  onChangePermissions,
  onRemoveCollaborator,
}) => {
  const [openInviteDialog, setOpenInviteDialog] = useState(false);
  const [inviteUserId, setInviteUserId] = useState('');
  const [invitePermissions, setInvitePermissions] = useState<'view' | 'edit' | 'admin'>('view');

  const handleOpenInviteDialog = () => {
    setOpenInviteDialog(true);
  };

  const handleCloseInviteDialog = () => {
    setOpenInviteDialog(false);
    setInviteUserId('');
    setInvitePermissions('view');
  };

  const handleInviteSubmit = () => {
    if (inviteUserId) {
      onInviteUser(parseInt(inviteUserId), invitePermissions);
      handleCloseInviteDialog();
    }
  };

  return (
    <Box sx={{ mt: 4 }}>
      <Typography variant="h6" gutterBottom>
        Project Sharing & Permissions
      </Typography>

      <Button
        variant="contained"
        startIcon={<PersonAddIcon />}
        onClick={handleOpenInviteDialog}
        sx={{ mb: 2 }}
      >
        Invite User
      </Button>

      <List>
        {collaborators.length > 0 ? (
          collaborators.map((collab) => (
            <ListItem
              key={collab.id}
              secondaryAction={
                <>
                  <FormControl sx={{ minWidth: 120, mr: 1 }} size="small">
                    <InputLabel id={`permissions-label-${collab.id}`}>Permissions</InputLabel>
                    <Select
                      labelId={`permissions-label-${collab.id}`}
                      value={collab.permissions}
                      label="Permissions"
                      onChange={(e) => onChangePermissions(collab.id, e.target.value as 'view' | 'edit' | 'admin')}
                    >
                      <MenuItem value="view">View</MenuItem>
                      <MenuItem value="edit">Edit</MenuItem>
                      <MenuItem value="admin">Admin</MenuItem>
                    </Select>
                  </FormControl>
                  <IconButton edge="end" aria-label="remove" onClick={() => onRemoveCollaborator(collab.id)}>
                    <PersonRemoveIcon />
                  </IconButton>
                </>
              }
            >
              <ListItemText primary={collab.name} secondary={`ID: ${collab.id}`} />
            </ListItem>
          ))
        ) : (
          <Typography variant="body2" color="text.secondary">No collaborators yet.</Typography>
        )}
      </List>

      <Dialog open={openInviteDialog} onClose={handleCloseInviteDialog}>
        <DialogTitle>Invite New Collaborator</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            id="userId"
            label="User ID or Email"
            type="text"
            fullWidth
            variant="standard"
            value={inviteUserId}
            onChange={(e) => setInviteUserId(e.target.value)}
          />
          <FormControl fullWidth margin="dense">
            <InputLabel id="invite-permissions-label">Permissions</InputLabel>
            <Select
              labelId="invite-permissions-label"
              value={invitePermissions}
              label="Permissions"
              onChange={(e) => setInvitePermissions(e.target.value as 'view' | 'edit' | 'admin')}
            >
              <MenuItem value="view">View</MenuItem>
              <MenuItem value="edit">Edit</MenuItem>
              <MenuItem value="admin">Admin</MenuItem>
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseInviteDialog}>Cancel</Button>
          <Button onClick={handleInviteSubmit} variant="contained">Invite</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ProjectSharing;

