import axios from 'axios';
import { getToken, removeToken } from './auth';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000'; // Default to localhost

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor to add JWT token to headers
api.interceptors.request.use(
  (config) => {
    const token = getToken();
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor to handle errors (e.g., 401 Unauthorized)
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response && error.response.status === 401) {
      // Unauthorized, clear token and redirect to login
      removeToken();
      // You might want to use react-router-dom's navigate here,
      // but for a service file, direct window redirect is often simpler
      window.location.href = '/login'; 
    }
    return Promise.reject(error);
  }
);

// --- API Functions ---

// Authentication
export const loginUser = (credentials: any) => api.post('/auth/token', new URLSearchParams(credentials));
export const registerUser = (userData: any) => api.post('/auth/register', userData);
export const fetchCurrentUser = () => api.get('/auth/users/me/');

// Projects
export const getProjects = () => api.get('/projects/');
export const getProject = (projectId: number) => api.get(`/projects/${projectId}`);
export const createProject = (projectData: any) => api.post('/projects/', projectData);
export const updateProject = (projectId: number, projectData: any) => api.put(`/projects/${projectId}`, projectData);
export const deleteProject = (projectId: number) => api.delete(`/projects/${projectId}`);

// Tasks & Subtasks
export const getTasks = (projectId: number) => api.get(`/projects/${projectId}/tasks/`);
export const getTask = (taskId: number) => api.get(`/tasks/${taskId}`);
export const createTask = (projectId: number, taskData: any) => api.post(`/projects/${projectId}/tasks/`, taskData);
export const updateTask = (taskId: number, taskData: any) => api.put(`/tasks/${taskId}`, taskData);
export const deleteTask = (taskId: number) => api.delete(`/tasks/${taskId}`);

export const getSubtasks = (taskId: number) => api.get(`/tasks/${taskId}/subtasks/`);
export const getSubtask = (subtaskId: number) => api.get(`/subtasks/${subtaskId}`);
export const createSubtask = (taskId: number, subtaskData: any) => api.post(`/tasks/${taskId}/subtasks/`, subtaskData);
export const updateSubtask = (subtaskId: number, subtaskData: any) => api.put(`/subtasks/${subtaskId}`, subtaskData);
export const deleteSubtask = (subtaskId: number) => api.delete(`/subtasks/${subtaskId}`);

// Attachments
export const uploadAttachment = (file: File, itemId: number, itemType: 'project' | 'task' | 'subtask') => {
  const formData = new FormData();
  formData.append('file', file);
  if (itemType === 'project') formData.append('project_id', itemId.toString());
  if (itemType === 'task') formData.append('task_id', itemId.toString());
  if (itemType === 'subtask') formData.append('subtask_id', itemId.toString());

  return api.post('/attachments/upload', formData, {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  });
};
export const downloadAttachment = (attachmentId: number) => api.get(`/attachments/${attachmentId}/download`, { responseType: 'blob' });
export const deleteAttachment = (attachmentId: number) => api.delete(`/attachments/${attachmentId}`);

// Comments
export const getComments = (itemId: number, itemType: 'project' | 'task' | 'subtask') => api.get(`/comments/${itemId}?item_type=${itemType}`);
export const createComment = (commentData: any) => api.post('/comments/', commentData);
export const deleteComment = (commentId: number) => api.delete(`/comments/${commentId}`);

// Dependencies
export const createDependency = (dependencyData: any) => api.post('/dependencies/', dependencyData);
export const getTaskDependencies = (taskId: number) => api.get(`/tasks/${taskId}/dependencies/`);
export const getSubtaskDependencies = (subtaskId: number) => api.get(`/subtasks/${subtaskId}/dependencies/`);
export const deleteDependency = (dependencyId: number) => api.delete(`/dependencies/${dependencyId}`);

// Users (for admin or specific purposes)
export const getUsers = () => api.get('/users/');
export const getUser = (userId: number) => api.get(`/users/${userId}`);

// Project Sharing
export const shareProject = (projectId: number, shareData: any) => api.post(`/projects/${projectId}/share`, shareData);
export const getProjectPermissions = (projectId: number) => api.get(`/projects/${projectId}/permissions`);

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import * as api from '../services/api'; // Import all API functions

// Generic data fetching hook
export const useFetchData = <TData, TError = unknown>(
  queryKey: string[],
  fetchFunction: (...args: any[]) => Promise<TData>,
  options?: object
) => {
  return useQuery<TData, TError>({
    queryKey,
    queryFn: fetchFunction,
    ...options,
  });
};

// Generic mutation hook
export const useMutateData = <TData, TError = unknown, TVariables = void>(
  mutationFunction: (variables: TVariables) => Promise<TData>,
  invalidateQueryKeys: string[] = []
) => {
  const queryClient = useQueryClient();
  return useMutation<TData, TError, TVariables>({
    mutationFn: mutationFunction,
    onSuccess: () => {
      invalidateQueryKeys.forEach(key => queryClient.invalidateQueries({ queryKey: [key] }));
    },
  });
};

// Example usage for projects
export const useProjects = () => {
  return useFetchData(['projects'], api.getProjects);
};

export const useProject = (projectId: number) => {
  return useFetchData(['project', projectId], () => api.getProject(projectId), {
    enabled: !!projectId, // Only fetch if projectId exists
  });
};

export const useCreateProject = () => {
  return useMutateData(api.createProject, ['projects']);
};

export const useUpdateProject = () => {
  return useMutateData(({ projectId, projectData }) => api.updateProject(projectId, projectData), ['projects', 'project']);
};

export const useDeleteProject = () => {
  return useMutateData(api.deleteProject, ['projects']);
};

